// nptoy main theme for nptoy. Same mechanism as the kit's Teal preset:
// one main colour drives BOTH the accent tokens (buttons / links / focus / info)
// AND the top bar + command bar (nav-* tokens). Generated by new-service.mjs.
import { setTokenOverride } from 'lilak-ui'

export const NPTOY = {
  "btn-primary-bg": "#e08514",
  "btn-primary-hover": "#be7111",
  "btn-primary-text": "#ffffff",
  "text-link": "#e08514",
  "text-link-hover": "#be7111",
  "border-focus": "#e08514",
  "input-focus-border": "#e08514",
  "info-bg": "#fbeede",
  "info-text": "#be7111",
  "selection-bg": "rgba(224,133,20,0.28)",
  "nav-bg": "#e08514",
  "nav-border": "#c57512",
  "nav-accent": "#c57512",
  "nav-text": "#ffffff",
  "nav-text-muted": "#f6dab9",
}

/** Apply the nptoy colour overrides on top of the active base theme (call after applyTheme()). */
export function applyMainColor() {
  for (const [name, value] of Object.entries(NPTOY)) setTokenOverride(name, value)
}

// Only 'bright' is offered — the main colour is fixed via overrides, so
// dark/lowcontrast barely differ. Add their ids back here to offer them.
export const ENABLED_THEMES = ['bright']
